package br.com.luvi.financaspessoais.transferencia.entity;import br.com.luvi.financaspessoais.conta.entity.ContaFinanceira;import br.com.luvi.financaspessoais.usuario.entity.Usuario;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="transferencias") public class Transferencia{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private ContaFinanceira origem;@ManyToOne(optional=false)private ContaFinanceira destino;@Column(nullable=false,precision=12,scale=2)private BigDecimal valor;@Column(nullable=false)private LocalDate data;@Column(length=200)private String descricao;@ManyToOne(optional=false)private Usuario usuarioCriacao;@Column(nullable=false)private LocalDateTime dataHoraCadastro;@PrePersist void pre(){if(dataHoraCadastro==null)dataHoraCadastro=LocalDateTime.now();}public Long getId(){return id;}public ContaFinanceira getOrigem(){return origem;}public void setOrigem(ContaFinanceira v){origem=v;}public ContaFinanceira getDestino(){return destino;}public void setDestino(ContaFinanceira v){destino=v;}public BigDecimal getValor(){return valor;}public void setValor(BigDecimal v){valor=v;}public LocalDate getData(){return data;}public void setData(LocalDate v){data=v;}public String getDescricao(){return descricao;}public void setDescricao(String v){descricao=v;}public Usuario getUsuarioCriacao(){return usuarioCriacao;}public void setUsuarioCriacao(Usuario v){usuarioCriacao=v;}public LocalDateTime getDataHoraCadastro(){return dataHoraCadastro;}}
